-- Read-only fingerprint of everything migration 013 touches (columns, constraints,
-- trigger, RLS, policies, table/column privileges, all rf_ functions).
-- Run with the owner role; compare with a database built from the repository.
-- Expected after 001-013 (PostgreSQL 16 and 18): see docs/PHIXAR-P0-NEON-AUTH-VERIFICATION.md.
WITH x AS (SELECT 'fn' k, p.proname||'('||pg_get_function_identity_arguments(p.oid)||')' n, md5(regexp_replace(p.prosrc,'\s+',' ','g'))||' def='||p.prosecdef||' vol='||p.provolatile::text||' cfg='||coalesce(array_to_string(p.proconfig,','),'')||' exec_runtime='||has_function_privilege('rf_runtime_login',p.oid,'EXECUTE')||' exec_public='||coalesce((SELECT bool_or(a.grantee=0) FROM aclexplode(p.proacl) a),true) v FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.proname LIKE 'rf_%'
UNION ALL SELECT 'col', c.table_name||'.'||c.column_name, c.data_type||' null='||c.is_nullable||' def='||coalesce(c.column_default,'') FROM information_schema.columns c WHERE c.table_schema='public' AND c.table_name IN ('rf_webauthn_credentials','rf_webauthn_challenges','rf_webauthn_grants','rf_webauthn_approvals','rf_mfa_bootstrap_codes','rf_organization_security_policy')
UNION ALL SELECT 'con', t.relname||'.'||(CASE WHEN c.contype='c' THEN md5(regexp_replace(pg_get_constraintdef(c.oid),'\s+','','g')) ELSE c.conname END), c.contype::text||' '||md5(regexp_replace(pg_get_constraintdef(c.oid),'\s+','','g')) FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid WHERE t.relname IN ('rf_webauthn_credentials','rf_webauthn_challenges','rf_webauthn_grants','rf_webauthn_approvals','rf_mfa_bootstrap_codes','rf_organization_security_policy') AND c.contype<>'n'
UNION ALL SELECT 'trg', t.relname||'.'||g.tgname, md5(pg_get_triggerdef(g.oid)) FROM pg_trigger g JOIN pg_class t ON t.oid=g.tgrelid WHERE NOT g.tgisinternal AND t.relname LIKE 'rf_webauthn%'
UNION ALL SELECT 'rls', c.relname, 'rls='||c.relrowsecurity||' force='||c.relforcerowsecurity FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND c.relkind='r' AND c.relname IN ('rf_webauthn_credentials','rf_webauthn_challenges','rf_webauthn_grants','rf_webauthn_approvals','rf_mfa_bootstrap_codes','rf_organization_security_policy')
UNION ALL SELECT 'pol', tablename||'.'||policyname, cmd||' '||array_to_string(roles,',')||' '||md5(coalesce(qual,'')||'|'||coalesce(with_check,'')) FROM pg_policies WHERE schemaname='public' AND tablename IN ('rf_webauthn_credentials','rf_webauthn_challenges','rf_webauthn_grants','rf_webauthn_approvals','rf_mfa_bootstrap_codes','rf_organization_security_policy')
UNION ALL SELECT 'tpriv', table_name||'.'||privilege_type, grantee FROM information_schema.role_table_grants WHERE table_schema='public' AND grantee IN ('rf_runtime_login','rf_runtime','PUBLIC') AND table_name IN ('rf_webauthn_credentials','rf_webauthn_challenges','rf_webauthn_grants','rf_webauthn_approvals','rf_mfa_bootstrap_codes','rf_organization_security_policy')
UNION ALL SELECT 'cpriv', table_name||'.'||column_name||'.'||privilege_type, grantee FROM information_schema.column_privileges WHERE table_schema='public' AND grantee IN ('rf_runtime_login','rf_runtime','PUBLIC') AND table_name IN ('rf_webauthn_credentials','rf_webauthn_challenges','rf_webauthn_grants','rf_webauthn_approvals','rf_mfa_bootstrap_codes','rf_organization_security_policy')
) SELECT k, count(*)::int n, md5(string_agg(n||'='||v,'|' ORDER BY n,v)) h FROM x GROUP BY k ORDER BY k;
